contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller, uint256 amount, bool claim, address to) public {
        address op = c.operator();
        address own = c.owner();
        bool callerAllowed = (caller == op || caller == own);

        uint256 toBefore = 0;
        if (to != address(0)) {
            toBefore = IERC20(c.clpToken()).balanceOf(to);
        }

        bool reverted;
        try c.withdrawAndUnwrap(amount, claim, to) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (callerAllowed) {
            assert(!reverted);
            if (to != address(0)) {
                assert(IERC20(c.clpToken()).balanceOf(to) == toBefore + amount);
            }
        } else {
            assert(reverted);
            if (to != address(0)) {
                assert(IERC20(c.clpToken()).balanceOf(to) == toBefore);
            }
        }
    }

    receive() external payable {}
}

