contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount, bool claim, address to) public payable {
        require(amount > 0, "amount must be positive");

        uint256 clpBefore = c.clpToken().balanceOf(address(c));

        bool reverted;
        try c.withdrawAndUnwrap(amount, claim, to) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (reverted) {
            assert(msg.sender != c.operator() && msg.sender != c.owner());
        } else {
            uint256 clpAfter = c.clpToken().balanceOf(address(c));
            if (to != address(0)) {
                assert(clpBefore >= amount || amount > clpBefore);
            }
        }
    }

    receive() external payable {}
}

contract InvMutTest {
