    }

    function run(uint256 amount, bool claim, address to) public payable {
        require(to != address(this), "to must not be this test contract");

        uint256 clpBefore = c.clpToken().balanceOf(address(c));
        uint256 toBefore = to == address(0) ? 0 : c.clpToken().balanceOf(to);

        c.withdrawAndUnwrap(amount, claim, to);

        uint256 clpAfter = c.clpToken().balanceOf(address(c));

        if (to == address(0)) {
            assert(clpAfter >= clpBefore);
        } else {
            assert(c.clpToken().balanceOf(to) >= toBefore + amount);
        }
    }

    receive() external payable {}
}

