contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run() public payable {
        require(true);

        uint256 expectedStaked;
        uint256 expectedEarned;
        bool stakedReverted;
        bool earnedReverted;

        try c.stakedBalance() returns (uint256 v) {
            expectedStaked = v;
            stakedReverted = false;
        } catch {
            stakedReverted = true;
        }

        try c.earned() returns (uint256 v) {
            expectedEarned = v;
            earnedReverted = false;
        } catch {
            earnedReverted = true;
        }

        C.Position memory pos;
        bool showReverted;
        try c.showPositions() returns (C.Position memory p) {
            pos = p;
            showReverted = false;
        } catch {
            showReverted = true;
        }

        assert(
            showReverted || stakedReverted || earnedReverted || (pos.staked == expectedStaked && pos.earned == expectedEarned)
        );
    }
}

