    constructor(C _c) {
        c = _c;
    }

    function run(address newOwner) public {
        address ownerBefore = c.owner();
        require(ownerBefore == address(this), "caller must be current owner");

        bool reverted;
        try c.transferOwnership(newOwner) {
            reverted = false;
        } catch {
            reverted = true;
        }

        address ownerAfter = c.owner();

        assert(reverted == (newOwner == address(0)) && (reverted || ownerAfter == newOwner));
    }
}

