contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint32 newPId, address newToken, address newRewards) public payable {
        (bool success, bytes memory ret) = address(c).call(
            abi.encodeWithSignature("setCvxPoolInfo(uint32,address,address)", newPId, newToken, newRewards)
        );
        require(success, "setCvxPoolInfo must succeed");

        (uint32 pId, address token, address rewards) = c.cvxPoolInfo();

        bool expectedShutdown;
        (bool ok, bytes memory data) = address(c).staticcall(
            abi.encodeWithSignature("isCvxShutdown()")
        );
        require(ok, "isCvxShutdown must succeed");
        expectedShutdown = abi.decode(data, (bool));

        bool actualShutdown = c.isCvxShutdown();

        assert(
            pId == newPId &&
            token == newToken &&
            rewards == newRewards &&
            actualShutdown == expectedShutdown
        );
    }
}

