contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount, bool claim, address to) public payable {
        require(to != address(this));

        uint256 beforeTo = IERC20(c.clpToken()).balanceOf(to);

        bool reverted;
        try c.withdrawAndUnwrap(amount, claim, to) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterTo = IERC20(c.clpToken()).balanceOf(to);
        uint256 received = afterTo - beforeTo;

        bool callerIsOwner = (msg.sender == c.owner());
        if (!reverted && callerIsOwner) {
            assert(received <= amount);
        }
    }
}

