contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller, uint256 amount) public payable {
        require(address(this).balance >= amount);
        bool isOperator = (caller == c.operator());
        bool isShutdown = c.isCvxShutdown();
        bool reverted;
        if (isOperator) {
            try c.depositAndStake{value: amount}(amount) { reverted = false; } catch { reverted = true; }
        } else {
            try c.depositAndStake{value: amount}(amount) { reverted = false; } catch { reverted = true; }
        }
        assert(!isOperator || (reverted == isShutdown));
    }
    receive() external payable {}
}

