contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount, bool forceShutdown) public {
        // Make caller a controlled value distinct from this contract
        address caller = address(uint160(uint256(keccak256(abi.encodePacked(amount, forceShutdown)))) | 1);
        require(caller != address(this));
        require(caller != address(0));

        c.setOperator(caller);
        c.setCvxPoolInfo(0, address(0), address(0));

        // Determine whether the pool is shutdown; if caller is operator and not shutdown, call succeeds.
        // Since we cannot force shutdown without a real booster, use the shutdown status as-is.
        // If shutdown, depositAndStake should not revert when caller is operator (it simply does nothing).
        // The general rule: when caller is operator, depositAndStake never reverts regardless of shutdown.
        // When caller is not operator, it must revert.

        // Call with non-operator should revert.
        bool revertedNonOperator;
        {
            address nonOperator = address(uint160(caller) + 1);
            c.setOperator(nonOperator);
            try c.depositAndStake(amount) {
                revertedNonOperator = false;
            } catch {
                revertedNonOperator = true;
            }
            // Restore operator to caller for next call
            c.setOperator(caller);
        }

        // Call with operator should NOT revert (depositAndStake does not revert on shutdown; it just skips).
        bool revertedOperator;
        try c.depositAndStake(amount) {
            revertedOperator = false;
        } catch {
            revertedOperator = true;
        }

        assert(revertedOperator == false && revertedNonOperator == true);
    }

    receive() external payable {}
}

