contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address rewardsAddr) public {
        uint256 reported;
        bool ok;

        // Configure the reward pool to an arbitrary address (may be zero, may be non-contract).
        c.setCvxPoolInfo(0, address(0), rewardsAddr);

        // Try the deciding call and capture whether it completed.
        try c.stakedBalance() returns (uint256 v) {
            reported = v;
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: if the call completes, its return value is exactly the reward-pool's
        // balanceOf(this) for the configured rewards address; if it reverts, it must be
        // because the call to the configured reward pool failed.
        if (ok) {
            (bool poolOk, bytes memory poolData) = rewardsAddr.staticcall(
                abi.encodeWithSignature("balanceOf(address)", address(c))
            );
            require(poolOk, "pool call must succeed when stakedBalance succeeds");
            assert(reported == abi.decode(poolData, (uint256)));
        } else {
            (bool poolOk, ) = rewardsAddr.staticcall(
                abi.encodeWithSignature("balanceOf(address)", address(c))
            );
            assert(!poolOk);
        }
    }

    receive() external payable {}
}

