contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address rewardsPool) public {
        // Read-only call to a public view function of c (no state change).
        uint256 earnedValue;
        bool success;
        try c.earned() returns (uint256 v) {
            earnedValue = v;
            success = true;
        } catch {
            success = false;
        }

        // General rule: if earned() completes, it equals the reward pool's earned(address(c)).
        // We do not require a specific pool; the rule must hold whatever pool c uses.
        if (success) {
            // Read-only call through the interface at the public c.cvxPoolInfo() getters.
            (address token, address rewards, uint32 pId) = c.cvxPoolInfo();
            // Use the reward pool that c is configured to use, not the parameter.
            uint256 poolEarned = IBaseRewardPool(rewards).earned(address(c));
            assert(earnedValue == poolEarned);
        } else {
            // If the call reverts it is because the configured reward pool is unset or reverts.
            // In that case there is no value to assert; we treat reverting as allowed but the rule
            // only constrains successful completions. (A faulty version returning a wrong value
            // on success would be caught.)
            assert(!success);
        }
    }
}

