        bool isOwner = (msg.sender == owner);
        bool reverted;
        try c.setOperator(newOperator) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assert(
            (isOwner && !reverted && c.operator() == newOperator) ||
            (!isOwner && reverted && c.operator() == originalOperator)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address recipient) public {
        c.setRewardsRecipient(recipient);
        assert(c.rewardsRecipient() == recipient);
    }
}

